/* ---- scan_blocks.comp ----
#version 450
// Inclusive prefix sum of 1024-element blocks (256 threads x 4 elements).
// Writes each block's total to sums[] for the next level.
layout(local_size_x = 256) in;
layout(set = 0, binding = 0, std430) readonly buffer Src { uint src[]; };
layout(set = 0, binding = 1, std430) buffer Work { uint work[]; };
layout(push_constant) uniform Push {
    uint in_offset;   // into src (from_src != 0) or work
    uint out_offset;  // into work
    uint sums_offset; // into work
    uint count;
    uint from_src;
} pc;
shared uint block[1024];
shared uint partial[256];
void main()
{
    uint lid = gl_LocalInvocationID.x;
    uint base = gl_WorkGroupID.x * 1024u;
    for (uint k = 0u; k < 4u; k++) {
        uint idx = base + lid + k * 256u;
        uint v = 0u;
        if (idx < pc.count)
            v = pc.from_src != 0u ? src[pc.in_offset + idx] : work[pc.in_offset + idx];
        block[lid + k * 256u] = v;
    }
    barrier();
    uint v0 = block[lid * 4u];
    uint v1 = v0 + block[lid * 4u + 1u];
    uint v2 = v1 + block[lid * 4u + 2u];
    uint v3 = v2 + block[lid * 4u + 3u];
    partial[lid] = v3;
    barrier();
    for (uint d = 1u; d < 256u; d <<= 1u) {
        uint t = lid >= d ? partial[lid - d] : 0u;
        barrier();
        partial[lid] += t;
        barrier();
    }
    uint prefix = lid > 0u ? partial[lid - 1u] : 0u;
    block[lid * 4u] = v0 + prefix;
    block[lid * 4u + 1u] = v1 + prefix;
    block[lid * 4u + 2u] = v2 + prefix;
    block[lid * 4u + 3u] = v3 + prefix;
    barrier();
    for (uint k = 0u; k < 4u; k++) {
        uint idx = base + lid + k * 256u;
        if (idx < pc.count)
            work[pc.out_offset + idx] = block[lid + k * 256u];
    }
    if (lid == 255u)
        work[pc.sums_offset + gl_WorkGroupID.x] = partial[255];
}
*/
