/* ---- scan_add.comp ----
#version 450
// Adds the scanned total of all earlier blocks to block (group + 1).
layout(local_size_x = 256) in;
layout(set = 0, binding = 1, std430) buffer Work { uint work[]; };
layout(push_constant) uniform Push { uint data_offset; uint sums_offset; uint count; } pc;
void main()
{
    uint block = gl_WorkGroupID.x + 1u;
    uint add = work[pc.sums_offset + block - 1u];
    for (uint k = 0u; k < 4u; k++) {
        uint idx = block * 1024u + gl_LocalInvocationID.x + k * 256u;
        if (idx < pc.count)
            work[pc.data_offset + idx] += add;
    }
}
*/
