/* ---- lighting.frag ----
#version 450
// Deferred lighting from sampled G-buffer textures: point lights with
// Lambert diffuse and quadratic falloff, plus emissive.
layout(set = 0, binding = 0) uniform sampler2D g_albedo;
layout(set = 0, binding = 1) uniform sampler2D g_normal;
layout(set = 0, binding = 2) uniform sampler2D g_emissive;
layout(set = 0, binding = 3) uniform sampler2D g_depth;
layout(set = 0, binding = 4) uniform Lights {
    vec4 pos_radius[32];
    vec4 color[32];
    vec4 inv_size; // 1/width, 1/height
    uint count;
} lights;
layout(location = 0) out vec4 o_color;
void main()
{
    ivec2 px = ivec2(gl_FragCoord.xy);
    vec3 albedo = texelFetch(g_albedo, px, 0).rgb;
    vec3 n = normalize(texelFetch(g_normal, px, 0).xyz);
    vec3 c = texelFetch(g_emissive, px, 0).rgb;
    vec3 p = vec3(gl_FragCoord.xy * lights.inv_size.xy, texelFetch(g_depth, px, 0).r);
    for (uint i = 0u; i < lights.count; i++) {
        vec3 d = lights.pos_radius[i].xyz - p;
        float dist2 = dot(d, d);
        float r = lights.pos_radius[i].w;
        float atten = max(0.0, 1.0 - dist2 / (r * r));
        float ndl = max(0.0, dot(n, d) * inversesqrt(max(dist2, 1e-8)));
        c += albedo * lights.color[i].rgb * (ndl * atten * atten);
    }
    o_color = vec4(c, 1.0);
}
*/
