/* ---- lighting_local.frag ----
#version 450
// The same lighting, reading the G-buffer from tile memory as input
// attachments (dynamic rendering local read).
layout(input_attachment_index = 0, set = 0, binding = 0) uniform subpassInput g_albedo;
layout(input_attachment_index = 1, set = 0, binding = 1) uniform subpassInput g_normal;
layout(input_attachment_index = 2, set = 0, binding = 2) uniform subpassInput g_emissive;
layout(input_attachment_index = 3, set = 0, binding = 3) uniform subpassInput g_depth;
layout(set = 0, binding = 4) uniform Lights {
    vec4 pos_radius[32];
    vec4 color[32];
    vec4 inv_size;
    uint count;
} lights;
layout(location = 0) out vec4 o_color;
void main()
{
    vec3 albedo = subpassLoad(g_albedo).rgb;
    vec3 n = normalize(subpassLoad(g_normal).xyz);
    vec3 c = subpassLoad(g_emissive).rgb;
    vec3 p = vec3(gl_FragCoord.xy * lights.inv_size.xy, subpassLoad(g_depth).r);
    for (uint i = 0u; i < lights.count; i++) {
        vec3 d = lights.pos_radius[i].xyz - p;
        float dist2 = dot(d, d);
        float r = lights.pos_radius[i].w;
        float atten = max(0.0, 1.0 - dist2 / (r * r));
        float ndl = max(0.0, dot(n, d) * inversesqrt(max(dist2, 1e-8)));
        c += albedo * lights.color[i].rgb * (ndl * atten * atten);
    }
    o_color = vec4(c, 1.0);
}
*/
