/* ---- frame_cull.comp ----
#version 450
// Tiled light culling: the depth range of a 16x16 tile (shared atomics),
// then each thread tests one light against the tile's box. The lights that
// touch it are listed in index order (a shared bit mask and popcounts): a
// count and up to 63 indices per tile.
layout(local_size_x = 16, local_size_y = 16) in;
layout(set = 0, binding = 0) uniform sampler2D depth;
layout(set = 0, binding = 1, std430) readonly buffer Lights { vec4 pos_radius[256]; vec4 color[256]; } lights;
layout(set = 0, binding = 2, std430) writeonly buffer Tiles { uint data[]; } tiles;
layout(push_constant) uniform Push { vec2 inv_size; uint tiles_x; uint light_count; } pc;
shared uint s_min, s_max;
shared uint s_mask[8];
void main()
{
    uint i = gl_LocalInvocationIndex;
    if (i == 0u) {
        s_min = 0xFFFFFFFFu;
        s_max = 0u;
    }
    if (i < 8u)
        s_mask[i] = 0u;
    barrier();
    ivec2 px = min(ivec2(gl_GlobalInvocationID.xy), textureSize(depth, 0) - 1);
    float d = texelFetch(depth, px, 0).r;
    atomicMin(s_min, floatBitsToUint(d));
    atomicMax(s_max, floatBitsToUint(d));
    barrier();
    vec3 lo = vec3(vec2(gl_WorkGroupID.xy * 16u) * pc.inv_size, uintBitsToFloat(s_min));
    vec3 hi = vec3(vec2(gl_WorkGroupID.xy * 16u + 16u) * pc.inv_size, uintBitsToFloat(s_max));
    bool hit = false;
    if (i < pc.light_count) {
        vec4 l = lights.pos_radius[i];
        vec3 dd = clamp(l.xyz, lo, hi) - l.xyz;
        hit = dot(dd, dd) <= l.w * l.w;
        if (hit)
            atomicOr(s_mask[i >> 5u], 1u << (i & 31u));
    }
    barrier();
    uint tile = gl_WorkGroupID.y * pc.tiles_x + gl_WorkGroupID.x;
    uint before = uint(bitCount(s_mask[i >> 5u] & ((1u << (i & 31u)) - 1u)));
    for (uint w = 0u; w < (i >> 5u); w++)
        before += uint(bitCount(s_mask[w]));
    if (hit && before < 63u)
        tiles.data[tile * 64u + 1u + before] = i;
    if (i == 0u) {
        uint n = 0u;
        for (uint w = 0u; w < 8u; w++)
            n += uint(bitCount(s_mask[w]));
        tiles.data[tile * 64u] = min(n, 63u);
    }
}
*/
