/* ---- frame_light.frag ----
#version 450
// Tiled deferred lighting: the G-buffer, a 4-cascade shadow map (2x2 PCF
// through a comparison sampler) and the lights of the pixel's tile.
layout(set = 0, binding = 0) uniform sampler2D g_albedo;
layout(set = 0, binding = 1) uniform sampler2D g_normal;
layout(set = 0, binding = 2) uniform sampler2D g_emissive;
layout(set = 0, binding = 3) uniform sampler2D g_depth;
layout(set = 0, binding = 4) uniform sampler2DArrayShadow shadow;
layout(set = 0, binding = 5, std430) readonly buffer Lights { vec4 pos_radius[256]; vec4 color[256]; } lights;
layout(set = 0, binding = 6, std430) readonly buffer Tiles { uint data[]; } tiles;
layout(push_constant) uniform Push { vec2 inv_size; uint tiles_x; uint pad; } pc;
layout(location = 0) out vec4 o_color;
void main()
{
    ivec2 px = ivec2(gl_FragCoord.xy);
    vec3 albedo = texelFetch(g_albedo, px, 0).rgb;
    vec3 n = normalize(texelFetch(g_normal, px, 0).xyz);
    vec3 c = texelFetch(g_emissive, px, 0).rgb;
    float z = texelFetch(g_depth, px, 0).r;
    vec3 p = vec3(gl_FragCoord.xy * pc.inv_size, z);
    // Cascade k holds the screen scaled by 2^-k about its centre; a quarter
    // texel offset keeps the lookups away from texel edges.
    uint cascade = min(uint(z * 4.0), 3u);
    vec2 suv = (p.xy - 0.5) * exp2(-float(cascade)) + (0.5 + 0.25 / 2048.0);
    float sh = 0.0;
    for (int k = 0; k < 4; k++) {
        vec2 o = vec2(float(k & 1), float(k >> 1)) * (1.0 / 2048.0);
        sh += texture(shadow, vec4(suv + o, float(cascade), z - 0.002));
    }
    sh *= 0.25;
    uint tile = (uint(px.y) / 16u) * pc.tiles_x + uint(px.x) / 16u;
    uint count = tiles.data[tile * 64u];
    for (uint i = 0u; i < count; i++) {
        uint li = tiles.data[tile * 64u + 1u + i];
        vec3 d = lights.pos_radius[li].xyz - p;
        float dist2 = dot(d, d);
        float r = lights.pos_radius[li].w;
        float atten = max(0.0, 1.0 - dist2 / (r * r));
        float ndl = max(0.0, dot(n, d) * inversesqrt(max(dist2, 1e-8)));
        c += albedo * lights.color[li].rgb * (ndl * atten * atten);
    }
    o_color = vec4(c * (0.25 + 0.75 * sh), 1.0);
}
*/
