/* ---- frame_bloom.frag ----
#version 450
// Bloom: four bilinear taps half a destination texel around the pixel, from
// the next larger level (downsampling) or the next smaller one (upsampling,
// blended additively).
layout(set = 0, binding = 0) uniform sampler2D src;
layout(push_constant) uniform Push { vec2 inv_size; vec2 pad; } pc;
layout(location = 0) out vec4 o;
void main()
{
    vec2 uv = gl_FragCoord.xy * pc.inv_size;
    vec2 d = 0.5 * pc.inv_size;
    o = 0.25 * (texture(src, uv - d) + texture(src, uv + vec2(d.x, -d.y)) + texture(src, uv + vec2(-d.x, d.y)) +
                texture(src, uv + d));
}
*/
